    const iv = crypto.getRandomValues(new Uint8Array(12));
    const key = await getCryptoKey(passphrase, ['encrypt']);
    const cipher = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, enc.encode(plainText));
    const ivStr = btoa(String.fromCharCode(...iv));
    const cipherStr = btoa(String.fromCharCode(...new Uint8Array(cipher)));
    return `${ivStr}:${cipherStr}`;
  }

  async function decryptPassword(encryptedPayload, passphrase) {
    try {
      const [ivBase64, cipherBase64] = encryptedPayload.split(':');
      if (!ivBase64 || !cipherBase64) return null;

      const iv = Uint8Array.from(atob(ivBase64), c => c.charCodeAt(0));
      const cipher = Uint8Array.from(atob(cipherBase64), c => c.charCodeAt(0));
      const key = await getCryptoKey(passphrase, ['decrypt']);

      const decrypted = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, cipher);
      return new TextDecoder().decode(decrypted);
    } catch (err) {
      console.error('[QuickLogin] Lỗi giải mã mật khẩu:', err);
      return null;
    }
  }

