  // ================= 11. TẢI DỮ LIỆU & TỰ ĐỘNG DI CHUYỂN DỮ LIỆU CŨ (AUTO-MIGRATION) =================
  async function checkAndMigrateOldData(data) {
    if (!data) return data;
    const keys = Object.keys(data);
    let needMigration = false;

    // Kiểm tra xem có tài khoản nào còn trường 'alias' hoặc thiếu 'oder'/'createat'/'id' hay không
    for (const key of keys) {
      const acc = data[key];
      if (acc.alias !== undefined || acc.oder === undefined || acc.createat === undefined || !acc.id) {
        needMigration = true;
        break;
      }
    }

    if (!needMigration) return data;

    console.log('[QuickLogin] Phát hiện dữ liệu cũ, đang tự động chuẩn hóa cấu trúc mới...');
    const patchPayload = {};
    const defaultDate = new Date().toISOString();

    keys.forEach((key, index) => {
      const acc = data[key];
      const standardizedOrder = acc.oder !== undefined ? Number(acc.oder) : (index + 1);
      const standardizedId = acc.id || key;
      const standardizedCreatedAt = acc.createat || defaultDate;

      // Cập nhật cấu trúc mới, loại bỏ trường alias bằng cách gán null
      patchPayload[key] = {
        id: standardizedId,
        accountname: acc.accountname || acc.username || '',
        username: acc.username || acc.accountname || '',
        password: acc.password,
        avatar: acc.avatar || '',
        createat: standardizedCreatedAt,
        oder: standardizedOrder,
        alias: null
      };

      // Đồng bộ trực tiếp vào bộ nhớ cục bộ
      data[key] = {
        ...data[key],
        id: standardizedId,
        createat: standardizedCreatedAt,
        oder: standardizedOrder
      };
      delete data[key].alias;
    });

    try {
      const targetUrl = `${CONFIG.dbBaseUrl}/danhsachdangnhapnhanh.json?auth=${encodeURIComponent(CONFIG.dbSecret)}`;
      const res = await fetch(targetUrl, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(patchPayload)
      });
      if (res.ok) {
        console.log('[QuickLogin] Chuẩn hóa toàn bộ dữ liệu tài khoản thành công!');
      }
    } catch (err) {
      console.error('[QuickLogin] Lỗi khi chuẩn hóa dữ liệu cũ:', err);
    }

    return data;
  }

  async function fetchAccounts() {
    try {
      const res = await fetch(`${CONFIG.dbBaseUrl}/danhsachdangnhapnhanh.json?auth=${CONFIG.dbSecret}`);
      if (!res.ok) throw new Error('Fetch failed');
      let data = await res.json();

      // Kiểm tra và tự động nâng cấp cấu trúc nếu phát hiện tài khoản cũ
      data = await checkAndMigrateOldData(data || {});

      accountsMap = data || {};
      renderGrid(accountsMap);
    } catch (err) {
      console.error('[QuickLogin] Lỗi kết nối:', err);
      listTarget.innerHTML = `<div class="om-ql-loading" style="color:#ef4444">Không thể tải dữ liệu!</div>`;
    }
  }

  function renderGrid(mapData) {
    listTarget.innerHTML = '';

    // Chuyển sang mảng và sắp xếp theo trường 'oder'
    const accountEntries = Object.keys(mapData).map(key => ({
      key,
      ...mapData[key]
    }));

    accountEntries.sort((a, b) => Number(a.oder || a.order || 0) - Number(b.oder || b.order || 0));

    // Render danh sách tài khoản theo đúng trật tự oder
    accountEntries.forEach(acc => {
      const avatarSrc = acc.avatar || `https://ui-avatars.com/api/?name=${encodeURIComponent(acc.username || acc.accountname)}&background=0284c7&color=fff&size=96`;

      const item = document.createElement('div');
      item.className = 'om-ql-item';
      item.innerHTML = `
        <div class="om-ql-more-btn" title="Chỉnh sửa hoặc xóa">&#8942;</div>
        <img src="${avatarSrc}" class="om-ql-avatar" alt="${acc.username}">
        <span class="om-ql-name" title="${acc.username}">${acc.username}</span>
        <span class="om-ql-accountname">${acc.accountname}</span>
      `;

      const moreBtn = item.querySelector('.om-ql-more-btn');
      moreBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        openEditModal(acc.key, acc);
      });

      item.addEventListener('click', async (e) => {
        e.stopPropagation();
        closeModal();
        await thucHienDangNhapHIS(acc);
      });

      listTarget.appendChild(item);
    });

    // Thẻ thêm mới ở vị trí n + 1
    const addItem = document.createElement('div');
    addItem.className = 'om-ql-item om-ql-item-add';
    addItem.title = 'Thêm tài khoản mới';
    addItem.innerHTML = `
      <div class="om-ql-add-icon">+</div>
      <span class="om-ql-name" style="color:#0284c7; font-weight:700;">Thêm mới</span>
      <span class="om-ql-accountname">Tài khoản</span>
    `;

    addItem.addEventListener('click', (e) => {
      e.stopPropagation();
      openAddNewModal();
    });

    listTarget.appendChild(addItem);
  }

  // ================= 12. TỰ ĐỘNG ĐĂNG NHẬP HIS =================
  async function thucHienDangNhapHIS(acc) {
    console.log(`[QuickLogin] Đang đăng nhập tài khoản: ${acc.accountname}`);

    const rawPassword = await decryptPassword(acc.password, CONFIG.passkey);
    if (!rawPassword) {
      alert('Không thể giải mã mật khẩu! Khóa xác thực không đúng.');
      return;
    }

    const userEl = document.querySelector(CONFIG.usernameSelector);
    const passEl = document.querySelector(CONFIG.passwordSelector);
    const captchaInputEl = document.querySelector(CONFIG.captchaInputSelector);
    const textEl = document.querySelector(CONFIG.captchaTextSelector);
    const reloadTarget = document.querySelector(CONFIG.captchaReloadSelector);

    if (!userEl || !passEl) {
      alert('Không tìm thấy các trường đăng nhập trên trang!');
      return;
    }

    clearInputValue(userEl);
    clearInputValue(passEl);
    clearInputValue(captchaInputEl);

    setInputValue(userEl, acc.accountname);
    setInputValue(passEl, rawPassword);

    if (!reloadTarget || !textEl) {
      const code = giaiCaptcha();
      if (captchaInputEl && code) setInputValue(captchaInputEl, code);
      kichHoatNutDangNhap();
      return;
    }

    const oldContent = textEl.innerHTML;
    let daXuLy = false;

    const tiepTucDangNhap = () => {
      if (daXuLy) return;
      daXuLy = true;
      const code = giaiCaptcha();
      if (captchaInputEl && code) setInputValue(captchaInputEl, code);
      kichHoatNutDangNhap();
    };

    const observer = new MutationObserver(() => {
      if (textEl.innerHTML !== oldContent && textEl.innerHTML.includes("ooo")) {
        observer.disconnect();
        tiepTucDangNhap();
      }
    });

    observer.observe(textEl, { childList: true, subtree: true, characterData: true });

    setTimeout(() => {
      observer.disconnect();
      tiepTucDangNhap();
    }, 350);

    reloadTarget.click();
    reloadTarget.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true, view: window }));
  }

  fetchAccounts();
})();

