    // 2. Chuẩn hóa họ tên thành slug định danh Firebase
    function toSlug(str) {
        if (!str) return '';
        return str
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .replace(/[đĐ]/g, 'd')
            .toLowerCase()
            .replace(/[^a-z0-9]/g, '')
            .trim();
    }

    // 3. Quét thông tin người dùng từ thẻ <a class="mau"> (hỗ trợ cả iframe và window.top)
    function detectCurrentUser() {
        const checkDoc = (doc) => {
            try {
                if (!doc) return null;
                const el = doc.querySelector('a.mau');
                if (el) {
                    const name = (el.innerText || el.textContent || '').trim();
                    if (name.length > 1) return name;
                }
            } catch (e) {}
            return null;
        };

        let foundName = checkDoc(document);
        if (!foundName) {
            try { if (window.top) foundName = checkDoc(window.top.document); } catch (e) {}
        }
        if (!foundName) {
            try { if (window.parent) foundName = checkDoc(window.parent.document); } catch (e) {}
        }

        return foundName;
    }

    // 4. BƯỚC ĐẦU TIÊN: Kiểm tra trạng thái trên Firebase trước khi thực thi
    const authWatcher = setInterval(async () => {
        const detectedName = detectCurrentUser();
        if (detectedName) {
            clearInterval(authWatcher);
            currentUser = detectedName;
            currentUserKey = toSlug(detectedName);
            firebaseEndpoint = `${DB_BASE_URL}/users/${currentUserKey}.json?auth=${DB_SECRET}`;

            await checkStateAndInit();
        }
    }, 500);

    setTimeout(() => clearInterval(authWatcher), 30000);

