            (document.head || document.documentElement).appendChild(dynamicStyle);
        }

        if (!isFeatureEnabled || !widthPx) {
            dynamicStyle.textContent = '';
            return;
        }

        dynamicStyle.textContent = `
            #gview_${TARGET_GRID_ID} .ui-jqgrid-htable th:nth-child(${NAME_COL_INDEX}),
            table#${TARGET_GRID_ID} tr.jqgfirstrow td:nth-child(${NAME_COL_INDEX}),
            table#${TARGET_GRID_ID} tr.jqgrow td:nth-child(${NAME_COL_INDEX}) {
                width: ${widthPx}px !important;
                min-width: ${widthPx}px !important;
                max-width: ${widthPx}px !important;
            }
        `;
    }

    function getTextWidth(text, font) {
        const canvas = getTextWidth.canvas || (getTextWidth.canvas = document.createElement('canvas'));
        const context = canvas.getContext('2d');
        context.font = font;
        return context.measureText(text).width;
    }

    function autoFitNameColumn(force = false) {
        if (!isFeatureEnabled) {
            currentCalculatedWidth = 0;
            applyDynamicColWidthCSS(null);
            return;
        }

        const grid = document.getElementById(TARGET_GRID_ID);
        if (!grid) return;

        const rows = grid.querySelectorAll('tr.jqgrow');
        if (!rows.length) return;

        const sampleCell = rows[0].querySelector(`td:nth-child(${NAME_COL_INDEX})`);
        if (!sampleCell) return;

        const computedStyle = window.getComputedStyle(sampleCell);
        const font = `${computedStyle.fontSize} ${computedStyle.fontFamily}`;

        let maxTextWidth = 0;
        rows.forEach(tr => {
            const cell = tr.querySelector(`td:nth-child(${NAME_COL_INDEX})`);
            if (!cell) return;
            const text = (cell.innerText || cell.textContent || '').trim();
            const width = getTextWidth(text, font);
            if (width > maxTextWidth) maxTextWidth = width;
        });

        if (maxTextWidth === 0) return;

        const targetWidth = Math.ceil(maxTextWidth + TRIGGER_WIDTH + 25);
        if (force || Math.abs(targetWidth - currentCalculatedWidth) > 3) {
            currentCalculatedWidth = targetWidth;
            applyDynamicColWidthCSS(targetWidth);
        }
    }

    function updateUIState() {
        const btn = document.getElementById('btnSortFollowed');

        if (isFeatureEnabled) {
            document.body.classList.add('follow-feature-active');
            autoFitNameColumn(true);
        } else {
            document.body.classList.remove('follow-feature-active');
            currentCalculatedWidth = 0;
            applyDynamicColWidthCSS(null);
        }

        if (!btn) return;

        btn.classList.remove('disconnected', 'mode-enabled', 'mode-disabled');

        if (!isFirebaseConnected) {
            btn.classList.add('disconnected');
            btn.title = 'Mất kết nối đám mây Firebase';
        } else if (isFeatureEnabled) {
            btn.classList.add('mode-enabled');
            btn.title = `[User: ${currentUser}] Đang BẬT theo dõi\n- Bấm: Ghim bệnh nhân lên đầu\n- Shift + Bấm: Tắt tính năng`;
        } else {
            btn.classList.add('mode-disabled');
            btn.title = `[User: ${currentUser}] Đang TẮT theo dõi\n- Shift + Bấm: Bật lại tính năng`;
        }
    }

    async function saveCloudData(newList, newEnabledState) {
        if (newList !== undefined) cachedFollowedList = newList;
        if (newEnabledState !== undefined) {
            isFeatureEnabled = newEnabledState;
            currentCalculatedWidth = 0;
        }

        updateUIState();
        syncStatus();
        autoFitNameColumn(true);

        const payload = {
            enabled: isFeatureEnabled,
            followed_patients: cachedFollowedList
        };

        try {
            const res = await fetch(firebaseEndpoint, {
                method: 'PUT',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
            });
            isFirebaseConnected = res.ok;
            updateUIState();
        } catch (err) {
            console.error(`Lỗi lưu trạng thái của User: ${currentUser}:`, err);
            isFirebaseConnected = false;
            updateUIState();
        }
    }

    function syncStatus() {
        const grid = document.getElementById(TARGET_GRID_ID);
        if (!grid) return;

        const rows = grid.querySelectorAll('tr.jqgrow');
        rows.forEach(tr => {
            const idCell = tr.querySelector('td[aria-describedby*="SOBENHAN_HT"]');
            const pId = idCell ? idCell.textContent.trim() : '';
            if (isFeatureEnabled && pId && cachedFollowedList.includes(pId)) {
                tr.setAttribute('data-followed', 'true');
            } else {
                tr.removeAttribute('data-followed');
            }
        });
        autoFitNameColumn();
    }

    function sortFollowed() {
        if (!isFirebaseConnected) {
            alert(`Chưa kết nối được với Firebase cho hồ sơ: [User: ${currentUser}]`);
            return;
        }

        const grid = document.getElementById(TARGET_GRID_ID);
        if (!grid) return;

        const tableBody = grid.querySelector('tbody') || grid;
        const rows = Array.from(grid.querySelectorAll('tr.jqgrow'));
        if (!rows.length) return;

        rows.sort((a, b) => {
            const idA = a.querySelector('td[aria-describedby*="SOBENHAN_HT"]')?.textContent.trim() || '';
            const idB = b.querySelector('td[aria-describedby*="SOBENHAN_HT"]')?.textContent.trim() || '';
            const followA = cachedFollowedList.includes(idA) ? -1 : 1;
            const followB = cachedFollowedList.includes(idB) ? -1 : 1;
            return followA - followB;
        });

        rows.forEach(tr => tableBody.appendChild(tr));
        autoFitNameColumn(true);
    }

    function bindGridEvents() {
        document.addEventListener('click', function(e) {
            if (!isFeatureEnabled) return;

            const targetCell = e.target.closest(`table#${TARGET_GRID_ID} tr.jqgrow td:nth-child(${NAME_COL_INDEX})`);
            if (!targetCell) return;

            const rect = targetCell.getBoundingClientRect();
            if ((e.clientX - rect.left) > (rect.width - TRIGGER_WIDTH)) {
                if (!e.shiftKey) return;

                const tr = targetCell.closest('tr');
                const idCell = tr.querySelector('td[aria-describedby*="SOBENHAN_HT"]');
                const pId = idCell ? idCell.textContent.trim() : '';
                const pName = targetCell.textContent.trim();

                if (!pId) return;

                let list = [...cachedFollowedList];
                const idx = list.indexOf(pId);

                if (confirm(idx > -1 ? `[User: ${currentUser}]\nBỏ theo dõi bệnh nhân: ${pName}?` : `[User: ${currentUser}]\nTheo dõi bệnh nhân: ${pName}?`)) {
                    if (idx > -1) {
                        list.splice(idx, 1);
                    } else {
                        list.push(pId);
                    }
                    saveCloudData(list, isFeatureEnabled);
                }
                e.stopPropagation();
            }
        }, true);
    }

    // Chỉ chèn nút khi có grid #list_benhnhan
    function handleButtonInjection() {
        const hasTargetGrid = !!document.getElementById(TARGET_GRID_ID);
        const existingBtn = document.getElementById('btnSortFollowed');

        if (!hasTargetGrid) {
            if (existingBtn) {
                existingBtn.remove();
            }
            return;
        }

        if (!existingBtn) {
            const refBtn = document.getElementById('lammoi') || document.querySelector('button[onclick*="lammoi"]');
            if (refBtn && refBtn.parentNode) {
                const btn = document.createElement('button');
                btn.id = 'btnSortFollowed';
                btn.type = 'button';
                // Gán class ban đầu theo trạng thái isFeatureEnabled
                btn.className = `btn-sort-followed ${isFeatureEnabled ? 'mode-enabled' : 'mode-disabled'}`;
                btn.innerHTML = HEROICON_STAR;

                btn.addEventListener('click', function(e) {
                    if (e.shiftKey) {
                        const nextState = !isFeatureEnabled;
                        const msg = nextState
                            ? `[User: ${currentUser}]\nBạn có muốn BẬT lại tính năng đánh dấu bệnh nhân không?`
                            : `[User: ${currentUser}]\nBạn có chắc chắn muốn TẮT tính năng đánh dấu bệnh nhân?\n(Cột nút tròn sẽ ẩn đi và nút chuyển sang màu xanh nhạt)`;

                        if (confirm(msg)) {
                            saveCloudData(cachedFollowedList, nextState);
                        }
                    } else {
                        if (!isFeatureEnabled) {
                            alert(`[User: ${currentUser}]\nTính năng đánh dấu đang TẮT.\nHãy nhấn [Shift + Click] vào nút ngôi sao để BẬT lại.`);
                            return;
                        }
                        sortFollowed();
                    }
                });

                refBtn.parentNode.insertBefore(btn, refBtn.nextSibling);
                updateUIState();
            }
        }
    }

    function startObserver() {
        if (observer) return;
        observer = new MutationObserver(() => {
            handleButtonInjection();

            if (document.getElementById(TARGET_GRID_ID)) {
                syncStatus();
                clearTimeout(resizeDebounce);
                resizeDebounce = setTimeout(() => autoFitNameColumn(false), 100);
            }
        });
        observer.observe(document.body, { childList: true, subtree: true });
    }
})();

