(function() {
    'use strict';

    // ==========================================
    // 1. CẤU HÌNH FIREBASE & XÁC THỰC
    // ==========================================
    const DB_BASE_URL = 'https://sodophongicu-default-rtdb.asia-southeast1.firebasedatabase.app';
    const FIREBASE_API_KEY = 'AIzaSyDqCON3zB25cWFfNzCoM9-SUnj07jroy20';

    const STORAGE_KEY_REFRESH_TOKEN = 'aquamarine_fb_refresh_token';
    const STORAGE_KEY_ID_TOKEN = 'aquamarine_fb_id_token';
    const STORAGE_KEY_EXPIRY = 'aquamarine_fb_token_expiry';

    const FOLDER_HIS = 'phongbenhnhanhis';
    const FOLDER_BACKUP = 'phongbenhnhan_backup';
    const FOLDER_LOGS = 'phongbenhnhan_logs';

    let idToken = localStorage.getItem(STORAGE_KEY_ID_TOKEN) || null;
    let tokenExpiryTime = parseInt(localStorage.getItem(STORAGE_KEY_EXPIRY), 10) || 0;
    let authPromise = null;

    async function refreshExistingToken(savedRefreshToken) {
        try {
            const res = await fetch(`https://securetoken.googleapis.com/v1/token?key=${FIREBASE_API_KEY}`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                body: `grant_type=refresh_token&refresh_token=${encodeURIComponent(savedRefreshToken)}`
            });
            if (!res.ok) throw new Error(`Refresh token failed`);
            const data = await res.json();
            idToken = data.id_token;
            tokenExpiryTime = Date.now() + ((parseInt(data.expires_in, 10) || 3600) * 1000);
            localStorage.setItem(STORAGE_KEY_ID_TOKEN, idToken);
            localStorage.setItem(STORAGE_KEY_REFRESH_TOKEN, data.refresh_token);
            localStorage.setItem(STORAGE_KEY_EXPIRY, String(tokenExpiryTime));
            return idToken;
        } catch (err) {
            localStorage.removeItem(STORAGE_KEY_REFRESH_TOKEN);
            localStorage.removeItem(STORAGE_KEY_ID_TOKEN);
            localStorage.removeItem(STORAGE_KEY_EXPIRY);
            return null;
        }
    }

    async function createNewAnonymousSession() {
        try {
            const res = await fetch(`https://identitytoolkit.googleapis.com/v1/accounts:signUp?key=${FIREBASE_API_KEY}`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ returnSecureToken: true })
            });
            if (!res.ok) throw new Error(`Anonymous signUp failed`);
            const data = await res.json();
            idToken = data.idToken;
            tokenExpiryTime = Date.now() + ((parseInt(data.expiresIn, 10) || 3600) * 1000);
            localStorage.setItem(STORAGE_KEY_ID_TOKEN, idToken);
            localStorage.setItem(STORAGE_KEY_REFRESH_TOKEN, data.refreshToken);
            localStorage.setItem(STORAGE_KEY_EXPIRY, String(tokenExpiryTime));
            return idToken;
        } catch (err) { return null; }
    }

    async function getValidAuthToken() {
        if (idToken && Date.now() < tokenExpiryTime - 60000) return idToken;
        if (authPromise) return authPromise;
        authPromise = (async () => {
            try {
                const savedRefreshToken = localStorage.getItem(STORAGE_KEY_REFRESH_TOKEN);
                if (savedRefreshToken) {
                    const refreshedToken = await refreshExistingToken(savedRefreshToken);
                    if (refreshedToken) return refreshedToken;
                }
                return await createNewAnonymousSession();
            } finally { authPromise = null; }
        })();
        return authPromise;
    }

    function getCurrentHisUser() {
        const userEl = document.querySelector('.header_right a.mau') || document.querySelector('.header_right span.mau') || document.querySelector('.header_right');
        if (userEl) {
            const cleanText = (userEl.textContent || '').replace(/^[\s\(\[\{–—-]+|[\s\)\]\}–—-]+$/g, '').trim();
            if (cleanText) return cleanText;
        }
        return 'Ẩn danh / HIS Client';
    }

    function formatLogTimestamp(timestampMs) {
        const d = timestampMs ? new Date(timestampMs) : new Date();
        const yyyy = d.getFullYear();
        const MM = String(d.getMonth() + 1).padStart(2, '0');
        const dd = String(d.getDate()).padStart(2, '0');
        const hh = String(d.getHours()).padStart(2, '0');
        const mm = String(d.getMinutes()).padStart(2, '0');
        const ss = String(d.getSeconds()).padStart(2, '0');
        return `${yyyy}-${MM}-${dd} ${hh}:${mm}:${ss}`;
    }

    async function pushAuditLog(action, sba, fullname, fromRoom, toRoom) {
        try {
            const token = await getValidAuthToken();
            if (!token) return;
            const logPayload = {
                sba: String(sba).trim(), fullname: String(fullname).trim(),
                action: action, fromRoom: fromRoom || '', toRoom: toRoom || '',
                user: getCurrentHisUser(), timestamp: { ".sv": "timestamp" }
            };
            await fetch(`${DB_BASE_URL}/${FOLDER_LOGS}.json?auth=${token}`, {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
