    function syncJqGridColumnWidth(targetWidth) {
        if (!targetWidth || Math.abs(targetWidth - lastAppliedWidth) < 2) return;
        lastAppliedWidth = targetWidth;
        const $ = window.$ || window.jQuery;
        if ($ && $.fn && $.fn.jqGrid) {
            try { const $grid = $(`#${TARGET_GRID_ID}`); if ($grid.length && $grid[0].grid && typeof $grid.jqGrid('setColWidth') === 'function') { $grid.jqGrid('setColWidth', BED_COL_NAME, targetWidth, true); return; } } catch (e) {}
        }
        const thHeader = document.getElementById(BED_HEADER_ID);
        if (!thHeader) return;
        const colIndex = Array.from(thHeader.parentNode.children).indexOf(thHeader) + 1;
        if (colIndex <= 0) return;
        thHeader.style.width = `${targetWidth}px`;
        const innerDiv = thHeader.querySelector('div'); if (innerDiv) innerDiv.style.width = `${targetWidth}px`;
        const firstRowCell = document.querySelector(`table#${TARGET_GRID_ID} tr.jqgfirstrow td:nth-child(${colIndex})`); if (firstRowCell) firstRowCell.style.width = `${targetWidth}px`;
        const headerCol = document.querySelector(`.ui-jqgrid-htable colgroup col:nth-child(${colIndex})`); if (headerCol) headerCol.style.width = `${targetWidth}px`;
        const bodyCol = document.querySelector(`table#${TARGET_GRID_ID} colgroup col:nth-child(${colIndex})`); if (bodyCol) bodyCol.style.width = `${targetWidth}px`;
        document.querySelectorAll(`table#${TARGET_GRID_ID} tr.jqgrow td:nth-child(${colIndex})`).forEach(c => c.style.width = `${targetWidth}px`);
    }

    function autoFitBedColumn() {
        const grid = document.getElementById(TARGET_GRID_ID); if (!grid) return;
        const cells = grid.querySelectorAll(`tr.jqgrow ${BED_CELL_SELECTOR}`); if (!cells.length) return;
        let maxCalculated = 135;
        cells.forEach(cell => {
            const badge = cell.querySelector('.his-room-badge');
            const badgeWidth = badge ? badge.offsetWidth : 62;
            const originalContent = (cell.textContent || '').replace(badge ? badge.textContent : '', '').trim();
            const estimated = badgeWidth + (originalContent.length * 7.5) + 32;
            if (estimated > maxCalculated) maxCalculated = estimated;
        });
        syncJqGridColumnWidth(Math.ceil(maxCalculated));
    }

