    // 4. QUẢN LÝ DỮ LIỆU & ĐỒNG BỘ
    // ==========================================
    function extractPatientFromRow(tr) {
        const sba = (tr.querySelector('td[aria-describedby*="SOBENHAN_HT"]') || {}).textContent || '';
        const fullname = (tr.querySelector('td[aria-describedby*="TEN_BENH_NHAN_HT"]') || {}).textContent || '';
        const age = (tr.querySelector('td[aria-describedby*="NGAY_SINH"]') || {}).textContent || '';
        const gender = (tr.querySelector('td[aria-describedby*="GIOI_TINH"]') || {}).textContent || '';
        const addrCell = tr.querySelector('td[aria-describedby*="DIA_CHI"]');
        const address = addrCell ? (addrCell.getAttribute('title') || addrCell.textContent || '') : '';
        const ngayravien = (tr.querySelector(DISCHARGE_DATE_SELECTOR) || {}).textContent || '';
        return { sba: sba.trim(), fullname: fullname.trim(), age: age.trim(), gender: gender.trim(), address: address.trim(), ngayravien: toEmptyStr(ngayravien) };
    }

    function scanActivePatientsFromGrid() {
        const grid = document.getElementById(TARGET_GRID_ID); if (!grid) return [];
        const activePatients = [];
        grid.querySelectorAll('tr.jqgrow').forEach(tr => {
            const pInfo = extractPatientFromRow(tr);
            if (pInfo.sba) {
                const sbaKey = sanitizeKey(pInfo.sba);
                if (patientsRoomMap[sbaKey] && hasValue(patientsRoomMap[sbaKey].roomname)) pInfo.roomname = patientsRoomMap[sbaKey].roomname;
                activePatients.push(pInfo);
            }
        });
        return activePatients;
    }

    async function updateHisCardToCloud(sbaKey, dataObj) {
        if (!sbaKey || !isDataLoaded) return;
        const token = await getValidAuthToken(); if (!token) return;
        try { await fetch(`${DB_BASE_URL}/${FOLDER_HIS}/${sbaKey}.json?auth=${token}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(dataObj) }); } catch (e) {}
    }

    async function batchUpdateHisCardsToCloud(batchMap) {
        if (!batchMap || Object.keys(batchMap).length === 0 || !isDataLoaded) return;
        const token = await getValidAuthToken(); if (!token) return;
        try { await fetch(`${DB_BASE_URL}/${FOLDER_HIS}.json?auth=${token}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(batchMap) }); } catch (e) {}
    }

    async function updateBackupRoomSafe(sbaKey, newRoomName) {
        if (!sbaKey || !isDataLoaded || !hasValue(newRoomName)) return;
        const token = await getValidAuthToken(); if (!token) return;
        backupMemoryMap[sbaKey] = newRoomName;
        try { await fetch(`${DB_BASE_URL}/${FOLDER_BACKUP}/${sbaKey}.json?auth=${token}`, { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(newRoomName) }); } catch (e) {}
    }

    async function getBackupRoomLazy(sbaKey) {
        if (!sbaKey) return '';
        if (backupMemoryMap[sbaKey] !== undefined) return backupMemoryMap[sbaKey] || '';
        const token = await getValidAuthToken(); if (!token) return '';
        try {
            const res = await fetch(`${DB_BASE_URL}/${FOLDER_BACKUP}/${sbaKey}.json?auth=${token}`);
            if (res.ok) { const roomName = await res.json(); const cleanRoom = hasValue(roomName) ? String(roomName).trim() : ''; backupMemoryMap[sbaKey] = cleanRoom; return cleanRoom; }
        } catch (e) {}
        backupMemoryMap[sbaKey] = ''; return '';
    }

    async function processGridScanAndLifecycle() {
        if (!isDataLoaded || !isFilterAllChecked()) return;
        const gridPatients = scanActivePatientsFromGrid();
        const batchPayload = {}; let needsBatchUpdate = false;

        for (const p of gridPatients) {
            const sbaKey = sanitizeKey(p.sba);
            let hisCard = patientsRoomMap[sbaKey];
            if (!hisCard) {
                const initialStatus = hasValue(p.ngayravien) ? 'off' : 'on';
                const backupRoom = await getBackupRoomLazy(sbaKey);
                hisCard = { id: sbaKey, fullname: p.fullname, age: p.age, gender: p.gender, address: p.address, roomname: backupRoom || toEmptyStr(p.roomname), status: initialStatus, ngayravien: toEmptyStr(p.ngayravien), lastseen: Date.now() };
                patientsRoomMap[sbaKey] = hisCard;
                batchPayload[sbaKey] = { ...hisCard, lastseen: { ".sv": "timestamp" } }; needsBatchUpdate = true;
                if (hasValue(hisCard.roomname)) updateBackupRoomSafe(sbaKey, hisCard.roomname);
            } else {
                if (hisCard.ngayravien !== p.ngayravien) { hisCard.ngayravien = toEmptyStr(p.ngayravien); batchPayload[`${sbaKey}/ngayravien`] = hisCard.ngayravien; needsBatchUpdate = true; }
                if (hasValue(hisCard.ngayravien) && hisCard.status !== 'off') { hisCard.status = 'off'; batchPayload[`${sbaKey}/status`] = 'off'; needsBatchUpdate = true; }
                const requiredInterval = (30 + (Math.floor(Math.random() * 30) + 1)) * 60 * 1000;
                if (!hisCard.lastseen || (Date.now() - hisCard.lastseen) >= requiredInterval) {
                    hisCard.lastseen = Date.now(); batchPayload[`${sbaKey}/lastseen`] = { ".sv": "timestamp" }; needsBatchUpdate = true;
                }
            }
        }
        if (needsBatchUpdate) await batchUpdateHisCardsToCloud(batchPayload);
    }

    async function fetchPatientsDatabase() {
        if (!document.getElementById(TARGET_GRID_ID) || isFetching) return;
        isFetching = true;
        const token = await getValidAuthToken();
        if (!token) { isFetching = false; return; }
        try {
            const resHis = await fetch(`${DB_BASE_URL}/${FOLDER_HIS}.json?auth=${token}`);
            if (resHis && resHis.ok) {
                const data = await resHis.json(); patientsRoomMap = {};
                if (data && typeof data === 'object') {
                    for (const [key, item] of Object.entries(data)) {
                        if (!item) continue;
                        const sbaKey = item.id || key;
                        patientsRoomMap[sbaKey] = { id: sbaKey, fullname: toEmptyStr(item.fullname), age: toEmptyStr(item.age), gender: toEmptyStr(item.gender), address: toEmptyStr(item.address), roomname: toEmptyStr(item.roomname), status: item.status === 'off' ? 'off' : 'on', ngayravien: toEmptyStr(item.ngayravien), lastseen: typeof item.lastseen === 'number' ? item.lastseen : 0 };
                        if (hasValue(item.roomname)) backupMemoryMap[sbaKey] = item.roomname;
                    }
                }
                isDataLoaded = true;
                safeRenderBadgesOnGrid();
                await processGridScanAndLifecycle();
            }
        } catch (e) {} finally { isFetching = false; }
    }

    // ==========================================
    // 5. CỨU HỘ ĐƯỢC GỌI TỪ DASHBOARD EVENT
    // ==========================================
    window.addEventListener('RM_EXECUTE_RESTORE', async function() {
        const token = await getValidAuthToken();
        if (!token) { alert('Không thể xác thực quyền truy cập Firebase!'); return; }
        try {
            const res = await fetch(`${DB_BASE_URL}/${FOLDER_BACKUP}.json?auth=${token}`);
            if (!res.ok) { alert('Không thể kết nối đến Backup!'); return; }
            const backupData = await res.json();
            if (!backupData || typeof backupData !== 'object') { alert('Backup trống!'); return; }

            backupMemoryMap = { ...backupData };
            let restoreCount = 0; const gridPatients = scanActivePatientsFromGrid(); const batchPayload = {};

            for (const p of gridPatients) {
                const sbaKey = sanitizeKey(p.sba);
                const backupRoom = backupData[sbaKey];
                if (hasValue(backupRoom)) {
                    const currentCard = patientsRoomMap[sbaKey];
                    if (!currentCard || currentCard.roomname !== backupRoom) {
                        const oldRoom = currentCard ? currentCard.roomname : '';
                        if (!currentCard) {
                            const newCard = { id: sbaKey, fullname: p.fullname, age: p.age, gender: p.gender, address: p.address, ngayravien: p.ngayravien, roomname: backupRoom, status: 'on', lastseen: { ".sv": "timestamp" } };
                            batchPayload[sbaKey] = newCard; patientsRoomMap[sbaKey] = { ...newCard, lastseen: Date.now() };
                        } else {
                            currentCard.roomname = backupRoom; currentCard.status = 'on';
                            batchPayload[`${sbaKey}/roomname`] = backupRoom; batchPayload[`${sbaKey}/status`] = 'on';
                        }
                        restoreCount++;
                        pushAuditLog('ASSIGN', sbaKey, p.fullname, oldRoom, backupRoom);
                    }
                }
            }
            if (restoreCount > 0) {
                await batchUpdateHisCardsToCloud(batchPayload);
                safeRenderBadgesOnGrid(); renderRoomSchedules();
                alert(`Cứu hộ thành công: ${restoreCount} bệnh nhân!`);
            } else {
                alert('Buồng bệnh hiện tại đã trùng khớp hoàn toàn với bản sao lưu.');
            }
        } catch (err) { alert('Lỗi cứu hộ: ' + err.message); }
    });


