    function selectiveUpdateBadges() {
        const grid = document.getElementById(TARGET_GRID_ID); if (!grid) return;
        grid.querySelectorAll('tr.jqgrow').forEach(tr => {
            const bedCell = tr.querySelector(BED_CELL_SELECTOR); if (!bedCell) return;
            const sbaCell = tr.querySelector('td[aria-describedby*="SOBENHAN_HT"]');
            const sba = sbaCell ? sbaCell.textContent.trim() : ''; if (!sba) return;

            const sbaKey = sanitizeKey(sba);
            const targetRoomName = (patientsRoomMap[sbaKey] && hasValue(patientsRoomMap[sbaKey].roomname)) ? patientsRoomMap[sbaKey].roomname : '';

            let badge = bedCell.querySelector('.his-room-badge');
            if (badge && badge.getAttribute('data-sba') === sbaKey && badge.getAttribute('data-roomname') === targetRoomName) return;
            if (!badge) { badge = document.createElement('span'); badge.className = 'his-room-badge'; bedCell.insertBefore(badge, bedCell.firstChild); }
            badge.setAttribute('data-sba', sbaKey); badge.setAttribute('data-roomname', targetRoomName);
            badge.textContent = targetRoomName ? targetRoomName : '+ Phòng';
            badge.className = targetRoomName ? 'his-room-badge assigned' : 'his-room-badge unassigned';
        });
    }

    function safeRenderBadgesOnGrid() {
        if (!observer) { selectiveUpdateBadges(); autoFitBedColumn(); removeAllTooltips(); return; }
        observer.disconnect();
        try { selectiveUpdateBadges(); autoFitBedColumn(); removeAllTooltips(); } catch (err) {} finally { reconnectObserver(); }
    }

    function reconnectObserver() {
        if (!observer) return;
        const grid = document.getElementById(TARGET_GRID_ID);
        const observeTarget = (grid && grid.querySelector('tbody')) || grid || document.getElementById(`gbox_${TARGET_GRID_ID}`) || document.body;
        observer.observe(observeTarget, { childList: true, subtree: true });
    }

