    function renderLogLineElement(logItem) {
        const div = document.createElement('div'); const actionStr = logItem.action || 'TRANSFER';
        div.className = `rm-cloudrun-log-line action-${actionStr}`;
        div.innerHTML = `<span class="cr-time">${formatLogTimestamp(logItem.timestamp)}</span><span class="cr-pipe">|</span><span class="cr-action action-${actionStr}">${actionStr}</span><span class="cr-pipe">|</span><span class="cr-sba">${logItem.sba || 'N/A'}</span><span class="cr-pipe">|</span><span class="cr-name">${logItem.fullname || 'N/A'}</span><span class="cr-pipe">|</span><span class="cr-route">${logItem.fromRoom || 'Chưa gán'} -> ${logItem.toRoom || 'TRỐNG'}</span><span class="cr-pipe">|</span><span class="cr-user">by: ${logItem.user || 'Ẩn danh'}</span>`;
        return div;
    }

    async function openPatientLogModal(sbaKey, patientName) {
        const modal = document.getElementById('room-log-modal'); if (!modal) return;
        const feedContainer = document.getElementById('rm-log-feed-container');
        const endNotice = document.getElementById('rm-log-end-notice');
        feedContainer.innerHTML = '<div class="rm-log-end-status">Đang tải...</div>'; endNotice.style.display = 'none'; modal.classList.add('open');

        const token = await getValidAuthToken();
        if (!token) { feedContainer.innerHTML = '<div class="rm-log-end-status">Lỗi xác thực.</div>'; return; }
        try {
            const res = await fetch(`${DB_BASE_URL}/${FOLDER_LOGS}.json?auth=${token}&orderBy="sba"&equalTo="${encodeURIComponent(sbaKey)}"`);
            if (!res.ok) throw new Error(`Query failed`); const data = await res.json();
            feedContainer.innerHTML = '';
            if (!data || typeof data !== 'object' || Object.keys(data).length === 0) { feedContainer.innerHTML = '<div class="rm-log-end-status">— Chưa có logs —</div>'; return; }
            const logList = Object.entries(data).map(([key, item]) => ({ key, ...item })).sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));
            logList.forEach(item => feedContainer.appendChild(renderLogLineElement(item)));
            endNotice.style.display = 'block';
        } catch (err) { feedContainer.innerHTML = `<div class="rm-log-end-status" style="color:#ef4444;">Lỗi: ${err.message}</div>`; }
    }

    function openFloatingDetail(holderElement, roomCode, patientList) {
        removeFloatingDetail(); currentFloatingRoomCode = roomCode;
        const container = document.getElementById('rm-modal-grids-container'); if (!container) return;
        const holderRect = holderElement.getBoundingClientRect(); const containerRect = container.getBoundingClientRect();

        const floating = document.createElement('div'); floating.id = 'rm-floating-detail-panel'; floating.className = 'rm-floating-detail';
        let listHTML = patientList.length === 0 ? `<div class="rm-empty-state-compact">Phòng hiện đang trống</div>` : patientList.map(p => `
            <div class="rm-patient-item-detail ${activeTargetPatient && sanitizeKey(activeTargetPatient.sba) === p.id ? 'is-current' : ''}" data-sbakey="${p.id}">
                <div class="rm-patient-detail-left"><strong>${p.fullname}</strong> - ${p.age ? p.age.split('/').pop() : 'N/A'} - ${p.id}</div>
                <button type="button" class="rm-btn-item-history">🕒</button>
            </div>
        `).join('');

        floating.innerHTML = `
            <div class="rm-floating-header">
                <span class="rm-floating-header-title">Phòng: ${cleanRoomHeader(roomCode)} (${getAreaName(roomCode)})</span>
                <div class="rm-floating-actions"><button type="button" class="rm-floating-btn-delete" id="rm-btn-delete-card" style="display:none;">🗑️</button><button type="button" class="rm-floating-btn-pick" id="rm-btn-pick-room">+</button><button type="button" class="rm-floating-close-btn" id="rm-btn-close-floating">&times;</button></div>
            </div>
            <div class="rm-floating-body">${listHTML}</div>
        `;
        container.appendChild(floating);

        let left = (holderRect.left - containerRect.left) + container.scrollLeft;
        if ((left + (floating.offsetWidth || 350) + 10) > container.clientWidth) left = container.clientWidth - (floating.offsetWidth || 350) - 15;
        floating.style.top = `${(holderRect.top - containerRect.top) + container.scrollTop}px`; floating.style.left = `${left}px`;

        const deleteBtn = document.getElementById('rm-btn-delete-card');
        floating.querySelectorAll('.rm-patient-item-detail').forEach(cardEl => {
            cardEl.addEventListener('click', e => e.stopPropagation());
            const hBtn = cardEl.querySelector('.rm-btn-item-history');
            if (hBtn) hBtn.addEventListener('click', e => { e.stopPropagation(); openPatientLogModal(cardEl.getAttribute('data-sbakey'), ''); });
            cardEl.addEventListener('dblclick', e => {
                e.stopPropagation(); floating.querySelectorAll('.rm-patient-item-detail').forEach(c => { c.classList.remove('ready-to-delete'); const h = c.querySelector('.rm-btn-item-history'); if(h) h.style.display='none'; });
                cardEl.classList.add('ready-to-delete'); if (hBtn) hBtn.style.display = 'inline-flex';
                cardPendingDeleteSba = cardEl.getAttribute('data-sbakey'); if (deleteBtn) deleteBtn.style.display = 'inline-flex';
            });
        });

        if (deleteBtn) deleteBtn.addEventListener('click', async e => {
            e.stopPropagation(); if (!cardPendingDeleteSba) return;
            const card = patientsRoomMap[cardPendingDeleteSba]; if (!card) return;
            if (confirm(`Xác nhận XOÁ KHỎI PHÒNG?\n\n• Họ tên: ${card.fullname}\n• SBA: ${card.id}`)) {
                const oldRoomName = card.roomname || ''; card.status = 'off'; card.roomname = '';
                await updateHisCardToCloud(cardPendingDeleteSba, { status: 'off', roomname: '' });
                pushAuditLog('DISCHARGE', cardPendingDeleteSba, card.fullname, oldRoomName, 'TRỐNG');
                cardPendingDeleteSba = null; deleteBtn.style.display = 'none';
                renderRoomSchedules(); if (currentFloatingRoomCode) refreshFloatingPopoverContent(currentFloatingRoomCode);
            }
        });
        document.getElementById('rm-btn-pick-room').addEventListener('click', e => { e.stopPropagation(); handleAssignRoom(roomCode, holderElement); });
