    function refreshFloatingPopoverContent(roomCode) {
        const holderEl = document.querySelector(`.rm-room-holder[data-roomcode="${roomCode}"]`); if (!holderEl) return;
        openFloatingDetail(holderEl, roomCode, Object.values(patientsRoomMap).filter(pt => pt.roomname === roomCode && pt.status === 'on'));
    }

    function renderRoomSchedules() {
        const container = document.getElementById('rm-modal-grids-container'); if (!container) return;
        container.innerHTML = ''; const currentInRooms = {};
        Object.values(patientsRoomMap).forEach(pt => { if (pt && pt.status === 'on' && hasValue(pt.roomname)) { if (!currentInRooms[pt.roomname]) currentInRooms[pt.roomname] = []; currentInRooms[pt.roomname].push(pt); } });

        Object.keys(SCHEMAS).forEach(key => {
            const schema = SCHEMAS[key]; let total = 0; schema.rooms.forEach(r => { if (r && currentInRooms[r]) total += currentInRooms[r].length; });
            const section = document.createElement('div'); section.className = 'rm-section-box';
            section.innerHTML = `<div class="rm-section-title"><span>${schema.title}</span><span class="badge-count">${total} bệnh nhân</span></div><div class="rm-rooms-grid" id="grid-${key}"></div>`;
            container.appendChild(section); const gridContainer = document.getElementById(`grid-${key}`);

            schema.rooms.forEach(roomCode => {
                const cell = document.createElement('div');
                if (roomCode === null) { cell.className = 'rm-empty-holder'; } else {
                    const list = currentInRooms[roomCode] || []; cell.className = 'rm-room-holder'; cell.setAttribute('data-roomcode', roomCode);
                    let compactHTML = list.length === 0 ? `<div class="rm-empty-state-compact">Trống</div>` : list.slice(0,6).map(p => `<div class="rm-patient-compact-text ${activeTargetPatient && sanitizeKey(activeTargetPatient.sba)===p.id?'is-target':''}">• <strong>${p.fullname}</strong></div>`).join('');
                    if(list.length>6) compactHTML += `<div class="rm-patient-compact-text" style="color:#0066cc;font-weight:700;">+ ${list.length-6} BN khác...</div>`;
                    cell.innerHTML = `<div class="rm-holder-header"><span>${cleanRoomHeader(roomCode)}</span><span class="rm-holder-count">${list.length}</span></div><div class="rm-holder-list-compact">${compactHTML}</div>`;
                    cell.addEventListener('click', e => { e.stopPropagation(); openFloatingDetail(cell, roomCode, list); });
                }
                gridContainer.appendChild(cell);
            });
        });
    }

    async function handleAssignRoom(targetRoomName, holderElement) {
        if (!activeTargetPatient || !isDataLoaded) return;
        const sbaKey = sanitizeKey(activeTargetPatient.sba); const existingCard = patientsRoomMap[sbaKey];
        const oldRoom = existingCard && hasValue(existingCard.roomname) ? existingCard.roomname : '';
        if (existingCard && hasValue(existingCard.roomname) && targetRoomName === existingCard.roomname) return;
        const payload = { roomname: targetRoomName, status: 'on' };
        if (!existingCard) {
            Object.assign(payload, { id: sbaKey, fullname: activeTargetPatient.fullname, age: activeTargetPatient.age, gender: activeTargetPatient.gender, address: activeTargetPatient.address, ngayravien: toEmptyStr(activeTargetPatient.ngayravien), lastseen: { ".sv": "timestamp" } });
            patientsRoomMap[sbaKey] = { ...payload, lastseen: Date.now() };
        } else { existingCard.roomname = targetRoomName; existingCard.status = 'on'; }
        safeRenderBadgesOnGrid(); renderRoomSchedules();
        openFloatingDetail(document.querySelector(`.rm-room-holder[data-roomcode="${targetRoomName}"]`) || holderElement, targetRoomName, Object.values(patientsRoomMap).filter(pt => pt.roomname === targetRoomName && pt.status === 'on'));
        await updateHisCardToCloud(sbaKey, payload); updateBackupRoomSafe(sbaKey, targetRoomName);
        pushAuditLog(hasValue(oldRoom) ? 'TRANSFER' : 'ASSIGN', sbaKey, activeTargetPatient.fullname, oldRoom, targetRoomName);
    }

    function bindGridEvents() {
        document.addEventListener('click', e => {
            const badge = e.target.closest(`table#${TARGET_GRID_ID} tr.jqgrow ${BED_CELL_SELECTOR} .his-room-badge`);
            if (badge) { e.preventDefault(); e.stopPropagation(); const tr = badge.closest('tr'); if (tr) { const p = extractPatientFromRow(tr); if (p.sba) openModal(p); } }
            const thSort = e.target.closest(`.ui-jqgrid-htable th.ui-th-column, .ui-jqgrid-htable th[id*="${TARGET_GRID_ID}"]`);
            if (thSort) { clearTimeout(sortRefreshDebounce); sortRefreshDebounce = setTimeout(safeRenderBadgesOnGrid, 60); }
            const pagerBtn = e.target.closest('.ui-pg-button, .ui-icon-refresh, td[id*="refresh_"], .trangthaikham');
            if (pagerBtn) { clearTimeout(sortRefreshDebounce); sortRefreshDebounce = setTimeout(safeRenderBadgesOnGrid, 100); }
        }, true);
    }

    function startObserver() {
        if (observer) return;
        observer = new MutationObserver(mutations => {
            if (isModalOpen || !isDepartmentValid()) return;
            if (document.getElementById(TARGET_GRID_ID)) {
                if (!isInitialized) { isInitialized = true; injectStyles(); createModalDOM(); bindShortcutKeys(); bindGridEvents(); fetchPatientsDatabase(); return; }
                if (!isDataLoaded || !mutations.some(m => m.type === 'childList' && (m.addedNodes.length > 0 || m.removedNodes.length > 0))) return;
                clearTimeout(scanDebounce); scanDebounce = setTimeout(async () => { safeRenderBadgesOnGrid(); await processGridScanAndLifecycle(); }, 100);
            }
        });
        reconnectObserver();
    }

    function bootstrap() {
        startObserver();
        if (isDepartmentValid() && document.getElementById(TARGET_GRID_ID)) { isInitialized = true; injectStyles(); createModalDOM(); bindShortcutKeys(); bindGridEvents(); fetchPatientsDatabase(); }
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', bootstrap); else bootstrap();
})();

