            .db-run-btn {
                background: #0066cc; color: #ffffff; border: 1px solid #0052a3; padding: 8px 16px; font-size: 13px; font-weight: 800;
                border-radius: 6px; cursor: pointer; display: flex; align-items: center; gap: 6px; transition: all 0.15s ease; flex-shrink: 0;
            }
            .db-run-btn:hover { background: #0052a3; transform: translateY(-1px); box-shadow: 0 2px 6px rgba(0, 102, 204, 0.4); }
        `;
        (document.head || document.documentElement).appendChild(style);
    }

    // ==========================================
    // 4. UI BUILD & SỰ KIỆN CHUYỂN TAB
    // ==========================================
    function createDashboardDOM() {
        if (document.getElementById('room-dashboard-modal')) return;
        injectDashboardStyles();

        const backdrop = document.createElement('div');
        backdrop.id = 'room-dashboard-modal';
        backdrop.className = 'db-modal-backdrop';
        backdrop.innerHTML = `
            <div class="db-modal-card">
                <div class="db-modal-header">
                    <div class="db-tabs-container">
                        <button type="button" class="db-tab-btn active" data-target="db-tab-history">
                            <span class="db-tab-icon">↺</span> SYSTEM LOGS
                        </button>
                        <button type="button" class="db-tab-btn" data-target="db-tab-settings">
                            <span class="db-tab-icon">⚙️</span> SETTINGS
                        </button>
                    </div>
                    <button type="button" id="db-btn-close" class="db-modal-close-btn">&times;</button>
                </div>
                <div class="db-modal-body">
                    <!-- TAB HISTORY -->
                    <div id="db-tab-history" class="db-tab-pane active">
                        <div class="db-log-feed" id="db-log-feed-container"></div>
                        <div class="rm-log-scroll-loader" id="db-log-loader" style="display: none;">
                            <div class="rm-spinner"></div>
                            <span>Đang tải thêm các sự kiện tiếp theo...</span>
                        </div>
                        <div class="rm-log-end-status" id="db-log-end-notice" style="display: none;">
                            — Đã tải hết logs ghi nhận —
                        </div>
                    </div>

                    <!-- TAB SETTING -->
                    <div id="db-tab-settings" class="db-tab-pane">
                        <div class="db-setting-box">
                            <label class="db-setting-left">
                                <input type="checkbox" class="db-checkbox" id="db-restore-cb">
                                <span class="db-setting-text">KHÔI PHỤC DANH SÁCH BUỒNG BỆNH TỪ BACKUP</span>
                            </label>
                            <button type="button" class="db-run-btn" id="db-btn-run-restore">▶ RUN</button>
                        </div>
                    </div>
                </div>
            </div>
        `;
        document.body.appendChild(backdrop);

        // Đóng Modal
        document.getElementById('db-btn-close').addEventListener('click', closeDashboard);

        // Chuyển Tab
        document.querySelectorAll('.db-tab-btn').forEach(btn => {
            btn.addEventListener('click', () => {
                document.querySelectorAll('.db-tab-btn').forEach(b => b.classList.remove('active'));
                document.querySelectorAll('.db-tab-pane').forEach(p => p.classList.remove('active'));
                btn.classList.add('active');
                document.getElementById(btn.getAttribute('data-target')).classList.add('active');
            });
        });

        // Cuộn Infinite Scroll Tab History
        const logBodyScroll = document.getElementById('db-tab-history');
        logBodyScroll.addEventListener('scroll', () => {
            if (systemLogState.isLoading || !systemLogState.hasMore) return;
            const threshold = 40;
            if (logBodyScroll.scrollHeight - logBodyScroll.scrollTop - logBodyScroll.clientHeight <= threshold) {
                loadNextSystemLogsBatch();
            }
        });

        // Run Cứu Hộ
        document.getElementById('db-btn-run-restore').addEventListener('click', () => {
            const isChecked = document.getElementById('db-restore-cb').checked;
            if (!isChecked) {
                alert('Vui lòng đánh dấu vào ô vuông xác nhận trước khi nhấn RUN!');
                return;
            }
            if (confirm('XÁC NHẬN CỨU HỘ:\n\nBạn có chắc chắn muốn khôi phục toàn bộ buồng bệnh từ bản sao lưu gần nhất?')) {
                // Phát lệnh thực thi sang RoomModal (Script Core)
                window.dispatchEvent(new CustomEvent('RM_EXECUTE_RESTORE'));

                // Reset checkbox
                document.getElementById('db-restore-cb').checked = false;
                closeDashboard();
            }
        });
    }

    function toggleDashboard() {
        const modal = document.getElementById('room-dashboard-modal');
        if (!modal) return;
        if (modal.classList.contains('open')) {
            modal.classList.remove('open');
        } else {
            modal.classList.add('open');
            // Đảm bảo mở lên là tab Log hiển thị và bắt đầu tải log
            document.querySelector('.db-tab-btn[data-target="db-tab-history"]').click();
            resetAndLoadInitialLogs();
        }
    }

    function closeDashboard() {
        const modal = document.getElementById('room-dashboard-modal');
        if (modal) modal.classList.remove('open');
    }

    // ==========================================
    // 5. HIỂN THỊ SYSTEM LOGS
    // ==========================================
    function renderLogLineElement(logItem) {
        const div = document.createElement('div');
        const actionStr = logItem.action || 'TRANSFER';
        div.className = `rm-cloudrun-log-line action-${actionStr}`;

        div.innerHTML = `
            <span class="rm-log-toggle">▶</span>
            <div class="rm-log-content">
                <span class="cr-time">${formatLogTimestamp(logItem.timestamp)}</span><span class="cr-pipe">|</span><span class="cr-action action-${actionStr}">${actionStr}</span><span class="cr-pipe">|</span><span class="cr-sba">${logItem.sba || 'N/A'}</span><span class="cr-pipe">|</span><span class="cr-name">${logItem.fullname || 'N/A'}</span><span class="cr-pipe">|</span><span class="cr-route">${logItem.fromRoom || 'Chưa gán'} -> ${logItem.toRoom || 'TRỐNG'}</span><span class="cr-pipe">|</span><span class="cr-user">by: ${logItem.user || 'Ẩn danh'}</span>
            </div>
        `;

        // Cài đặt xử lý khi click Expand/Collapse
        div.addEventListener('click', function() {
            if (div.classList.contains('has-overflow')) {
                div.classList.toggle('expanded');
                const icon = div.querySelector('.rm-log-toggle');
                if (div.classList.contains('expanded')) {
                    icon.textContent = '▼';
                } else {
                    icon.textContent = '▶';
                }
            }
        });

        return div;
    }

    async function resetAndLoadInitialLogs() {
        document.getElementById('db-log-feed-container').innerHTML = '';
        systemLogState = { isLoading: false, hasMore: true, lastTimestampCursor: null, loadedKeys: new Set() };
        document.getElementById('db-log-end-notice').style.display = 'none';
        await loadNextSystemLogsBatch();
    }

    async function loadNextSystemLogsBatch() {
        if (systemLogState.isLoading || !systemLogState.hasMore) return;
        systemLogState.isLoading = true;

        const feedContainer = document.getElementById('db-log-feed-container');
        const loader = document.getElementById('db-log-loader');
        const endNotice = document.getElementById('db-log-end-notice');
        loader.style.display = 'flex';

        // Lấy hoặc tự tạo token mới nếu Core chưa tạo
        const token = await getValidAuthToken();
        if (!token) {
            loader.style.display = 'none'; systemLogState.isLoading = false;
            feedContainer.innerHTML = '<div class="rm-log-end-status" style="color:#ef4444;">Lỗi: Không thể kết nối Firebase (Hệ thống xác thực từ chối).</div>';
            return;
        }

        try {
            const FETCH_LIMIT = 15;
            let queryUrl = `${DB_BASE_URL}/${FOLDER_LOGS}.json?auth=${token}&orderBy="timestamp"&limitToLast=${FETCH_LIMIT}`;
            if (systemLogState.lastTimestampCursor !== null) {
                queryUrl = `${DB_BASE_URL}/${FOLDER_LOGS}.json?auth=${token}&orderBy="timestamp"&endAt=${systemLogState.lastTimestampCursor}&limitToLast=${FETCH_LIMIT + 1}`;
            }

            const res = await fetch(queryUrl);
            loader.style.display = 'none';
            if (!res.ok) throw new Error(`Fetch failed`);

            const data = await res.json();
            if (!data || typeof data !== 'object' || Object.keys(data).length === 0) {
                systemLogState.hasMore = false;
                if (feedContainer.children.length === 0) feedContainer.innerHTML = '<div class="rm-log-end-status">— Hệ thống chưa có bản ghi log nào —</div>';
                else endNotice.style.display = 'block';
                systemLogState.isLoading = false; return;
            }

            const batchList = Object.entries(data).map(([key, item]) => ({ key, ...item }));
            batchList.sort((a, b) => (b.timestamp || 0) - (a.timestamp || 0));

            let newAdded = 0;
            batchList.forEach(item => {
                if (!systemLogState.loadedKeys.has(item.key)) {
                    systemLogState.loadedKeys.add(item.key);
                    feedContainer.appendChild(renderLogLineElement(item));
                    newAdded++;
                }
            });

            // Xử lý kiểm tra các log bị tràn để thêm icon ">"
            setTimeout(() => {
                document.querySelectorAll('.rm-cloudrun-log-line:not(.overflow-checked)').forEach(line => {
                    line.classList.add('overflow-checked');
                    const content = line.querySelector('.rm-log-content');
                    // Kiểm tra chiều dài nội dung cuộn được (cộng dôi 1px để tránh sai số sub-pixel)
                    if (content && content.scrollWidth > (content.clientWidth + 1)) {
                        line.classList.add('has-overflow');
                    }
                });
            }, 50);

            if (batchList.length > 0) {
                systemLogState.lastTimestampCursor = batchList[batchList.length - 1].timestamp;
            }

            if (newAdded === 0 || batchList.length < FETCH_LIMIT) {
                systemLogState.hasMore = false;
                endNotice.style.display = 'block';
            }
        } catch (err) {
            loader.style.display = 'none';
            feedContainer.innerHTML += `<div class="rm-log-end-status" style="color:#ef4444;">Lỗi tải dữ liệu. Hãy thử lại.</div>`;
        } finally {
            systemLogState.isLoading = false;
        }
    }

    // ==========================================
    // 6. KHỞI TẠO & LẮNG NGHE SỰ KIỆN TỪ CORE
    // ==========================================
    function bootstrap() {
        createDashboardDOM();
        // Lắng nghe tín hiệu kích hoạt Dashboard từ Script Core (khi ấn Option+Shift+R)
        window.addEventListener('RM_TOGGLE_DASHBOARD', toggleDashboard);
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', bootstrap);
    } else {
        bootstrap();
    }

})();
